<script lang="ts">
 import {onMount} from 'svelte';import {enter} from './motion';import {api} from './api';import type {Row} from './types';
 let {company,kind,options,fields,record=null,oncreated,onclose}:{company:number;kind:string;options:Row[];fields:Row[];record?:Row|null;oncreated:(result:Row)=>Promise<void>;onclose:()=>void}=$props();
 let dialog:HTMLDialogElement,origin=$state('India'),profile:Record<string,any>=$state({}),busy=$state(false),error=$state('');
 onMount(()=>{profile=record?structuredClone($state.snapshot(record.submission_profile)):{received_on:new Date().toLocaleDateString('en-CA'),measurements:[],additional:[]};profile.measurements||=[];profile.additional||=[];dialog.showModal()});
 function choices(f:Row){return options.filter(o=>o.company_id===company&&o.kind===f.options&&o.active&&(f.key!=='weave'||String(o.parent_id)===String(profile.category))&&(f.key!=='sub_item'||String(o.parent_id)===String(profile.weave)))}
 async function save(e:SubmitEvent){e.preventDefault();if(busy)return;busy=true;error='';const action=(e.submitter as HTMLButtonElement)?.value||'save';try{const result=await api(record?'/materials/'+record.id+'/workflow':'/material-references',record?{version:record.version,profile,action}:{company_id:company,kind,origin,profile,action});await oncreated({...result,message:action==='submit'?'Submitted to MD / Super Admin for approval.':'Material draft saved.'})}catch(e){error=(e as Error).message}finally{busy=false}}
</script>
<dialog bind:this={dialog} aria-labelledby="merchant-material-title" oncancel={e=>{if(busy)e.preventDefault();else onclose()}} use:enter><form onsubmit={save}><header><h2 id="merchant-material-title">{record?record.code+' · Edit material draft':'ETF/ESF Generate'}</h2><button type="button" disabled={busy} onclick={onclose}>Close</button></header><div class="body"><p>Complete the material details, save a draft, then submit to MD or Super Admin. Sourcing completes the private supplier details after approval.</p>{#if record?.review_note}<div class="review-note"><strong>Reviewer comments</strong><p>{record.review_note}</p></div>{/if}<div class="fields reference-fields"><label>Approved supplier<input value="Sourcing completes this after approval" readonly/></label>{#if !record}<label>Reference registered in<select bind:value={origin}><option value="India">India — ESF</option><option value="Dubai">Dubai — ETF</option></select></label>{:else}<label>Permanent reference<input value={record.code} readonly/></label>{/if}</div><p class="help">{record?'The permanent reference stays unchanged.':'India uses ESF; Dubai uses ETF. Your permanent number is generated when you first save.'}</p>
 {#each ['Specifications','Sample details'] as section}<h3>{section}</h3><div class="fields">{#each fields.filter(f=>f.section===section) as f}<label><span class="field-title">{f.label}{#if f.required&&!(kind==='trim'&&['category','weave'].includes(f.key))}<b aria-label="Required before submission"> *</b>{/if}</span>{#if f.type==='option'}<select bind:value={profile[f.key]} onchange={()=>{if(f.key==='category'){profile.weave='';profile.sub_item=''}if(f.key==='weave')profile.sub_item=''}}><option value="">Select…</option>{#each choices(f) as o}<option value={o.id}>{o.label}</option>{/each}</select>{:else if f.type==='select'}<select bind:value={profile[f.key]}><option value="">Select…</option>{#each f.options as v}<option>{v}</option>{/each}</select>{:else if f.type==='textarea'}<textarea rows="3" maxlength="2000" bind:value={profile[f.key]}></textarea>{:else}<input type={f.type==='date'?'date':f.type==='number'?'number':'text'} min={f.type==='number'?0:undefined} step={f.type==='number'?'any':undefined} maxlength="2000" readonly={f.key==='old_etf'&&!!record} bind:value={profile[f.key]}/>{/if}</label>{/each}</div>{/each}
 <h3>Measurements</h3>{#each profile.measurements||[] as m,i}<div class="measurement-row"><label>Weight<input type="number" min="0" step="any" bind:value={m.weight}/></label><label>Weight unit<select bind:value={m.weight_unit}><option>GSM</option><option>g/linear metre</option><option>oz/yd²</option></select></label><label>Width<input type="number" min="0" step="any" bind:value={m.width}/></label><label>Width unit<select bind:value={m.width_unit}><option>inch</option><option>cm</option><option>metre</option></select></label><button type="button" onclick={()=>profile.measurements.splice(i,1)}>Remove measurement</button></div>{/each}<button type="button" disabled={(profile.measurements?.length||0)>=20} onclick={()=>profile.measurements.push({weight:0,width:0,weight_unit:'GSM',width_unit:'inch'})}>Add weight / width</button>
 <h3>Additional details</h3>{#each profile.additional||[] as item,i}<div class="extra-row"><label>Field name<input maxlength="100" bind:value={item.label}/></label><label>Value<input maxlength="2000" bind:value={item.value}/></label><button type="button" onclick={()=>profile.additional.splice(i,1)}>Remove detail</button></div>{/each}<button type="button" disabled={(profile.additional?.length||0)>=30} onclick={()=>profile.additional.push({label:'',value:''})}>Add detail</button><p class="help">Fields marked * are required before submission. Supplier identities, commercial details and documents stay private. Returned comments appear here for correction.</p>{#if error}<p class="error" role="alert">{error}</p>{/if}</div><footer><button type="button" disabled={busy} onclick={onclose}>Cancel</button><button value="save" disabled={busy}>Save draft</button><button value="submit" class="primary" disabled={busy}>{busy?'Saving…':'Submit for approval'}</button></footer></form></dialog>
<style>dialog{width:calc(100vw - 24px);max-width:none;height:calc(100dvh - 24px);max-height:none;padding:0;border:1px solid #b6c5ce;border-radius:10px;color:#111;background:white}dialog::backdrop{background:#10263699}form{display:flex;flex-direction:column;height:100%;max-height:none}header{display:flex;align-items:center;justify-content:space-between;gap:16px;background:#132b40;color:white;padding:14px 20px}h2{color:white;margin:0;font-size:19px}.body{padding:16px 20px;overflow:auto;flex:1;min-height:0}header,footer{flex-shrink:0}h3{font-size:16px;margin:24px 0 12px}.measurement-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr)) auto;align-items:end;gap:12px;margin:12px 0}.fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px 16px;margin-top:16px}label{min-width:0;display:grid;gap:6px;font-size:13px;font-weight:600;color:#111}input,select,textarea{min-height:44px;padding:10px;border:1px solid #b6c5ce;border-radius:6px;background:#f2f8f8;color:#111;font:inherit}p{line-height:1.5;margin:0 0 16px}.help{font-size:13px;color:#374151;margin:16px 0 0}.error{color:#a12624;margin:12px 0 0}footer{display:flex;justify-content:flex-end;gap:12px;padding:12px 20px;border-top:1px solid #b6c5ce}button{min-height:44px;padding:10px 16px;border:1px solid #b6c5ce;border-radius:6px;background:white;color:#132b40;font:inherit;cursor:pointer}.primary{background:#087f83;color:white;border-color:#087f83}button:disabled{cursor:default;opacity:.7}.field-title{display:inline}.field-title b{display:inline;color:#a12624}.review-note{padding:14px 16px;background:#fff4d7;border:1px solid #dcc282;border-radius:8px;margin:12px 0}.review-note p{margin:6px 0 0;white-space:pre-wrap;overflow-wrap:anywhere}.extra-row{display:grid;grid-template-columns:1fr 2fr auto;align-items:end;gap:12px;margin:12px 0}textarea{resize:vertical}input[readonly]{background:#edf2f5}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #087f83;outline-offset:2px}.fields.reference-fields{grid-template-columns:repeat(2,minmax(0,1fr))}</style>
